<?php
defined('PREVENT_DIRECT_ACCESS') OR exit('No direct script access allowed');

/**
 * inventory_deliveries (+ inventory_delivery_items): the QR-coded delivery of
 * an approved inventory request.
 *
 *   ready       QR generated by inventory personnel; stock not yet touched
 *   in_transit  QR validated and release confirmed by delivery personnel;
 *               stock deducted ONCE, recorded in stock_movements
 *   delivered   delivery personnel handed it over at the learning center
 *
 * The QR code carries only qr_token (64 random hex characters). Everything
 * else is looked up and validated on the server.
 */
class InventoryDeliveryModel extends Model
{
    protected $table = 'inventory_deliveries';
    protected $primary_key = 'id';
    protected $fillable = [
        'delivery_code', 'request_id', 'active_request_id', 'qr_token', 'status', 'prepared_by', 'prepared_at',
        'released_by', 'released_at', 'qr_used_at', 'delivered_by', 'delivered_at', 'notes',
    ];

    /** Prefix printed in front of the token in the QR image, so stray QR codes are recognised. */
    public const QR_PREFIX = 'TESDANEXUS-DLV:';

    private function base()
    {
        return $this->db->table('inventory_deliveries d')
            ->select('d.id, d.delivery_code, d.request_id, d.status, d.prepared_at, d.released_at, d.qr_used_at,
                      d.delivered_at, d.notes, r.request_code, r.status AS request_status, r.training_center_id,
                      tc.name AS center_name, tc.address AS center_address,
                      pb.full_name AS prepared_by_name, rb.full_name AS released_by_name, db.full_name AS delivered_by_name')
            ->inner_join('inventory_requests r', 'r.id = d.request_id')
            ->inner_join('training_centers tc', 'tc.id = r.training_center_id')
            ->left_join('users pb', 'pb.id = d.prepared_by')
            ->left_join('users rb', 'rb.id = d.released_by')
            ->left_join('users db', 'db.id = d.delivered_by');
    }

    /** Deliveries newest first, optionally by status, with their items. */
    public function listing(array $statuses = [], $centerId = null)
    {
        $query = $this->base();
        if ($statuses) {
            $query->in('d.status', $statuses);
        }
        if ($centerId) {
            $query->where('r.training_center_id', (int) $centerId);
        }
        return $this->attach_items($query->order_by('d.id', 'DESC')->get_all());
    }

    public function detail($id)
    {
        $row = $this->base()->where('d.id', (int) $id)->get();
        return $row ? $this->attach_items([$row])[0] : null;
    }

    /** The active (not cancelled) delivery of a request, with its items. */
    public function for_request($requestId)
    {
        $row = $this->base()->where('d.request_id', (int) $requestId)->where('d.status', '!=', 'cancelled')->get();
        return $row ? $this->attach_items([$row])[0] : null;
    }

    /** The QR token of a delivery (only shown to staff who may print or scan it). */
    public function token($id)
    {
        $row = $this->db->table($this->table)->select('qr_token')->where('id', (int) $id)->get();
        return $row['qr_token'] ?? null;
    }

    /**
     * Finds a delivery from what was scanned or typed: the QR payload
     * ("TESDANEXUS-DLV:<token>"), the bare token, or the delivery reference
     * number (DLV-2026-0001) as the manual fallback.
     * Returns ['delivery' => row|null, 'via' => 'qr'|'code'|null].
     */
    public function lookup($input)
    {
        $input = trim((string) $input);
        if (stripos($input, self::QR_PREFIX) === 0) {
            $input = substr($input, strlen(self::QR_PREFIX));
        }
        if (preg_match('/^[a-f0-9]{64}$/i', $input)) {
            $row = $this->db->table($this->table)->select('id')->where('qr_token', strtolower($input))->get();
            return ['delivery' => $row ? $this->detail($row['id']) : null, 'via' => 'qr'];
        }
        if (preg_match('/^DLV-\d{4}-\d{1,6}$/i', $input)) {
            $row = $this->db->table($this->table)->select('id')->where('delivery_code', strtoupper($input))->get();
            return ['delivery' => $row ? $this->detail($row['id']) : null, 'via' => 'code'];
        }
        return ['delivery' => null, 'via' => null];
    }

    /**
     * Why a delivery cannot be released now (empty list = it can):
     * active QR, request approved and prepared, not already processed,
     * and the delivery items match the request's approved items.
     */
    public function problems(array $delivery)
    {
        $problems = [];
        if ($delivery['status'] === 'cancelled') {
            $problems[] = 'This QR code was cancelled and is no longer active.';
        }
        if ($delivery['qr_used_at'] || in_array($delivery['status'], ['in_transit', 'delivered'], true)) {
            $problems[] = 'This delivery was already released on ' . date('M j, Y g:i A', strtotime($delivery['released_at'] ?? $delivery['qr_used_at'])) . '. A QR code can only be processed once.';
        }
        if (!$problems && $delivery['request_status'] !== 'ready_for_delivery') {
            $problems[] = 'The inventory request is not marked ready for delivery.';
        }
        if (!$problems) {
            $approved = $this->db->table('inventory_request_items')
                ->select('product_id, quantity_requested, quantity_approved')
                ->where('request_id', (int) $delivery['request_id'])->get_all();
            $expected = [];
            foreach ($approved as $a) {
                $expected[(int) $a['product_id']] = (int) ($a['quantity_approved'] ?? $a['quantity_requested']);
            }
            $actual = [];
            foreach ($delivery['items'] as $i) {
                $actual[(int) $i['product_id']] = (int) $i['quantity'];
            }
            ksort($expected);
            ksort($actual);
            if ($expected !== $actual) {
                $problems[] = 'The delivery items no longer match the approved request. Ask inventory personnel to check it.';
            }
        }
        return $problems;
    }

    /**
     * Releases the delivery: marks the QR used and the delivery in transit,
     * deducts every item from stock, records each deduction in
     * stock_movements, moves the request to in_transit and records the
     * release on the blockchain ledger, all in one transaction.
     *
     * The first statement only succeeds while the delivery is still unused
     * (status = 'ready' AND qr_used_at IS NULL), so a second scan, a double
     * click or a parallel request cannot deduct stock twice. take_stock()
     * only subtracts when enough is left, so stock never goes negative.
     */
    public function release(array $delivery, $userId, ProductModel $products, AuditModel $audit)
    {
        $now = date('Y-m-d H:i:s');
        $this->db->transaction();
        try {
            $claimed = $this->db->table($this->table)
                ->where(['id' => (int) $delivery['id'], 'status' => 'ready'])
                ->where_null('qr_used_at')
                ->update(['status' => 'in_transit', 'qr_used_at' => $now, 'released_by' => $userId, 'released_at' => $now]);
            if (!$claimed) {
                throw new DomainException('This delivery was already released. A QR code can only be processed once.');
            }
            foreach ($delivery['items'] as $item) {
                if (!$products->take_stock((int) $item['product_id'], (int) $item['quantity'])) {
                    $left = $this->db->table('products')->select('quantity')->where('id', (int) $item['product_id'])->get();
                    throw new DomainException("Not enough {$item['product_name']} in stock: {$item['quantity']} needed, " . (int) ($left['quantity'] ?? 0) . ' left. Nothing was released.');
                }
                $this->db->table('stock_movements')->insert([
                    'product_id' => (int) $item['product_id'],
                    'movement_type' => 'release',
                    'quantity_change' => -1 * (int) $item['quantity'],
                    'request_id' => (int) $delivery['request_id'],
                    'delivery_id' => (int) $delivery['id'],
                    'training_center_id' => (int) $delivery['training_center_id'],
                    'remarks' => "Released for {$delivery['request_code']} ({$delivery['delivery_code']})",
                    'recorded_by' => $userId,
                ]);
            }
            $moved = $this->db->table('inventory_requests')
                ->where(['id' => (int) $delivery['request_id'], 'status' => 'ready_for_delivery'])
                ->update(['status' => 'in_transit', 'released_at' => $now]);
            if (!$moved) {
                throw new DomainException('The inventory request is no longer ready for delivery. Nothing was released.');
            }
            $audit->record('inventory_delivery', (int) $delivery['id'], 'released', $userId);
            $this->db->commit();
        } catch (Throwable $e) {
            $this->db->roll_back();
            throw $e;
        }
    }

    /** Delivery personnel hand the items over at the learning center. */
    public function mark_delivered(array $delivery, $userId)
    {
        $this->db->transaction();
        try {
            $changed = $this->db->table($this->table)
                ->where(['id' => (int) $delivery['id'], 'status' => 'in_transit'])
                ->update(['status' => 'delivered', 'delivered_by' => $userId, 'delivered_at' => date('Y-m-d H:i:s')]);
            if (!$changed) {
                throw new DomainException('Only a delivery in transit can be marked delivered.');
            }
            $this->db->table('inventory_requests')
                ->where(['id' => (int) $delivery['request_id'], 'status' => 'in_transit'])
                ->update(['status' => 'delivered']);
            $this->call->model('AuditModel');
            $this->AuditModel->record('inventory_delivery', (int) $delivery['id'], 'delivered', $userId);
            $this->db->commit();
        } catch (Throwable $e) {
            $this->db->roll_back();
            throw $e;
        }
    }

    /** [status => count] for the delivery dashboard. */
    public function status_counts()
    {
        $rows = $this->db->table($this->table)->select('status')->select_count('id', 'total')->group_by('status')->get_all();
        return array_map('intval', array_column($rows, 'total', 'status'));
    }

    private function attach_items(array $deliveries)
    {
        if (!$deliveries) {
            return $deliveries;
        }
        $rows = $this->db->table('inventory_delivery_items i')
            ->select('i.delivery_id, i.product_id, i.quantity, p.product_name, p.unit, p.quantity AS stock')
            ->inner_join('products p', 'p.id = i.product_id')
            ->in('i.delivery_id', array_column($deliveries, 'id'))
            ->order_by('p.product_name', 'ASC')
            ->get_all();
        $by = [];
        foreach ($rows as $row) {
            $row['quantity'] = (int) $row['quantity'];
            $row['stock'] = (int) $row['stock'];
            $by[$row['delivery_id']][] = $row;
        }
        foreach ($deliveries as &$d) {
            $d['items'] = $by[$d['id']] ?? [];
            $d['items_summary'] = implode(', ', array_map(fn ($i) => "{$i['product_name']} × {$i['quantity']}", $d['items']));
            $d['total_quantity'] = array_sum(array_column($d['items'], 'quantity'));
            $d['qr_status'] = $d['status'] === 'cancelled' ? 'cancelled' : ($d['qr_used_at'] ? 'used' : 'active');
        }
        return $deliveries;
    }
}
